/**
 * Aspirant Arcade 500-Shot Master Scene Catalog.
 *
 * Comprehensive library of 500 reusable character poses, emotional states,
 * product gameplay views, hostel moments, and celebrations for Arjun and Priya.
 *
 * Features On-Demand Generation: If a shot's image does not yet exist in public/scenes/catalog/,
 * the sceneImageGenerator automatically generates and caches it on the fly.
 */

export interface MouthAnchor {
  centerX: string;
  centerY: string;
  baseWidth: number;
  maxHeight: number;
  rotationDeg: number;
  lipColor: string;
}

export interface ShotDefinition {
  id: string;
  category: string;
  character: 'arjun' | 'priya' | 'both' | 'screen';
  mood: string;
  setting: string;
  camera: 'close_up' | 'medium_shot' | 'over_the_shoulder' | 'wide' | 'screen_focus';
  description: string;
  tags: string[];
  assetPath: string;
  fallbackAsset: string;
  mouth?: MouthAnchor;
}

export const ARJUN_DEFAULT_MOUTH: MouthAnchor = {
  centerX: '59.9%',
  centerY: '40.3%',
  baseWidth: 26,
  maxHeight: 16,
  rotationDeg: -5,
  lipColor: 'rgba(100, 45, 30, 0.95)',
};

export const PRIYA_DEFAULT_MOUTH: MouthAnchor = {
  centerX: '48.5%',
  centerY: '36.8%',
  baseWidth: 24,
  maxHeight: 15,
  rotationDeg: 1,
  lipColor: 'rgba(110, 40, 30, 0.95)',
};

